{
  "API_calls": [],
  "collected_information": {
    "python_version": "3.9+",
    "environment_setup": {
      "virtual_environment": "conda create -n metagpt python=3.9 && conda activate metagpt",
      "installation_options": [
        "pip install --upgrade metagpt",
        "pip install --upgrade git+https://github.com/geekan/MetaGPT.git",
        "git clone https://github.com/geekan/MetaGPT && cd MetaGPT && pip install --upgrade -e ."
      ],
      "config_file": "~/.metagpt/config2.yaml",
      "config_initialization_command": "metagpt --init-config",
      "LLM_API_keys_and_model_config": "used in config2.yaml"
    },
    "dependencies": {
      "exact_versions": {
        "aiohttp": "3.8.6",
        "channels": "4.0.0",
        "faiss_cpu": "1.7.4",
        "fire": "0.4.0",
        "typer": "0.9.0",
        "lancedb": "0.4.0",
        "loguru": "0.6.0",
        "meilisearch": "0.21.0",
        "numpy": ">=1.24.3",
        "openai": ">=1.6.1",
        "beautifulsoup4": "4.12.3",
        "pandas": "2.1.1",
        "pydantic": ">=2.5.3",
        "PyYAML": "6.0.1",
        "tqdm": "4.66.2"
      },
      "test_dependencies": "pytest, pytest-mock commented out and not installed by default"
    },
    "ci_workflows": {
      "python_version": "3.9 (Ubuntu latest runner)",
      "env_vars": {
        "ALLOW_OPENAI_API_CALL": "0"
      },
      "configuration": {
        "source": "tests/config2.yaml",
        "destination": "~/.metagpt/config2.yaml"
      },
      "dependency_installation": "sh tests/scripts/run_install_deps.sh",
      "test_command": "pytest tests/ --doctest-modules --cov=./metagpt/ --cov-report=xml:cov.xml --cov-report=html:htmlcov --durations=20 | tee unittest.txt",
      "coverage_reporting": [
        "coverage report -m",
        "upload to Codecov"
      ],
      "test_runs": {
        "directory_level": "tests/",
        "manual_specific_file_run": "pytest tests/test_llm_config.py"
      },
      "outputs": [
        "test durations",
        "coverage reports (XML, HTML)",
        "logs saved in unittest.txt"
      ]
    }
  },
  "terminate": true
}
